{"code": "# 计算单季度销售量
# 第一季度单季销量 = 第一季度累计值
# 后续季度单季销量 = 本季度累计值 - 上季度累计值
cumulative_sales = {
    '2019年第一季度': 1810.7,
    '2019年第二季度': 3734.5,
    '2019年第三季度': 5643.0,
    '2019年第四季度': 7426.8
}

quarters = ['2019年第一季度', '2019年第二季度', '2019年第三季度', '2019年第四季度']
quarterly_sales = {}

for i, q in enumerate(quarters):
    if i == 0:
        quarterly_sales[q] = cumulative_sales[q]
    else:
        quarterly_sales[q] = cumulative_sales[q] - cumulative_sales[quarters[i-1]]

print('单季度销售量计算结果（万台）：')
for q in quarters:
    print(f'{q}: {quarterly_sales[q]:.1f}')

# 计算环比增长率（第二、三、四季度相对于前一季度）
print('\n环比增长率计算：')
growth_rates = {}
for i in range(1, len(quarters)):
    current_q = quarters[i]
    previous_q = quarters[i-1]
    rate = (quarterly_sales[current_q] - quarterly_sales[previous_q]) / quarterly_sales[previous_q] * 100
    growth_rates[current_q] = rate
    print(f'{current_q} 环比增长率 = ({quarterly_sales[current_q]:.1f} - {quarterly_sales[previous_q]:.1f}) / {quarterly_sales[previous_q]:.1f} × 100% = {rate:.2f}%')

# 准备最终答案
growth_rate_list = []
for q in ['2019年第二季度', '2019年第三季度', '2019年第四季度']:
    growth_rate_list.append(f"{q}：{growth_rates[q]:+.2f}%")

answer = f"洗衣机2019年第二、三、四季度的销量环比增长率分别为：{'；'.join(growth_rate_list)}。第二季度销量增长，第三、四季度销量逐步下降。"
print('\n最终答案：')
print(answer)"}

